// =========================================================
// 3. Database Layer (IndexedDB Version 2)
// =========================================================
class BibleStorage {
  constructor() {
    this.dbName = "BibleWorkbenchDB";
    this.version = 2;
    this.db = null;
  }

  async open() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, this.version);
      request.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains("custom_bibles")) {
          db.createObjectStore("custom_bibles", { keyPath: "id" });
        }
        if (!db.objectStoreNames.contains("custom_commentaries")) {
          db.createObjectStore("custom_commentaries", { keyPath: "id" });
        }
        if (!db.objectStoreNames.contains("user_settings")) {
          db.createObjectStore("user_settings", { keyPath: "key" });
        }
        if (!db.objectStoreNames.contains("highlights")) {
          db.createObjectStore("highlights", { keyPath: "key" });
        }
        if (!db.objectStoreNames.contains("verse_notes")) {
          db.createObjectStore("verse_notes", { keyPath: "key" });
        }
        if (!db.objectStoreNames.contains("online_cache")) {
          db.createObjectStore("online_cache", { keyPath: "id" });
        }
      };
      request.onsuccess = (e) => {
        this.db = e.target.result;
        resolve(this.db);
      };
      request.onerror = (e) => reject(e);
    });
  }

  async getAllCustomBibles() {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("custom_bibles", "readonly");
      const store = tx.objectStore("custom_bibles");
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = (e) => reject(e);
    });
  }

  async saveCustomBible(bibleObj) {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("custom_bibles", "readwrite");
      const store = tx.objectStore("custom_bibles");
      const req = store.put(bibleObj);
      req.onsuccess = () => resolve(true);
      req.onerror = (e) => reject(e);
    });
  }

  async deleteCustomBible(id) {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("custom_bibles", "readwrite");
      const store = tx.objectStore("custom_bibles");
      const req = store.delete(id);
      req.onsuccess = () => resolve(true);
      req.onerror = (e) => reject(e);
    });
  }

  async getAllCustomCommentaries() {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("custom_commentaries", "readonly");
      const store = tx.objectStore("custom_commentaries");
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = (e) => reject(e);
    });
  }

  async saveCustomCommentary(commObj) {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("custom_commentaries", "readwrite");
      const store = tx.objectStore("custom_commentaries");
      const req = store.put(commObj);
      req.onsuccess = () => resolve(true);
      req.onerror = (e) => reject(e);
    });
  }

  async getAllHighlights() {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("highlights", "readonly");
      const store = tx.objectStore("highlights");
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = (e) => reject(e);
    });
  }

  async saveHighlight(hlObj) {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("highlights", "readwrite");
      const store = tx.objectStore("highlights");
      const req = store.put(hlObj);
      req.onsuccess = () => resolve(true);
      req.onerror = (e) => reject(e);
    });
  }

  async deleteHighlight(key) {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("highlights", "readwrite");
      const store = tx.objectStore("highlights");
      const req = store.delete(key);
      req.onsuccess = () => resolve(true);
      req.onerror = (e) => reject(e);
    });
  }

  async getAllNotes() {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("verse_notes", "readonly");
      const store = tx.objectStore("verse_notes");
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = (e) => reject(e);
    });
  }

  async saveNote(noteObj) {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("verse_notes", "readwrite");
      const store = tx.objectStore("verse_notes");
      const req = store.put(noteObj);
      req.onsuccess = () => resolve(true);
      req.onerror = (e) => reject(e);
    });
  }

  async deleteNote(key) {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("verse_notes", "readwrite");
      const store = tx.objectStore("verse_notes");
      const req = store.delete(key);
      req.onsuccess = () => resolve(true);
      req.onerror = (e) => reject(e);
    });
  }

  async getOnlineCache(id) {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("online_cache", "readonly");
      const store = tx.objectStore("online_cache");
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = (e) => reject(e);
    });
  }

  async saveOnlineCache(cacheObj) {
    await this.open();
    return new Promise((resolve, reject) => {
      const tx = this.db.transaction("online_cache", "readwrite");
      const store = tx.objectStore("online_cache");
      const req = store.put(cacheObj);
      req.onsuccess = () => resolve(true);
      req.onerror = (e) => reject(e);
    });
  }
}

const db = new BibleStorage();



// =========================================================
// 4. Workbench App State & Interactive Controller
// =========================================================
class BibleWorkbenchApp {
  constructor() {
    this.currentBook = 64; // 3 John default
    this.currentChapter = 1;
    this.currentVerse = 1;
    this.activeVersion = "CUV";
    this.activeLeftTab = "studyOutline";
    this.activeCommId = "burdick";
    this.activeDrawerTab = "search";
    this.layoutMode = 1;
    this.parallelVersions = ["CUV", "CNV", "CSB", "ESV"];

    this.customBibles = [];
    this.customCommentaries = [];
    this.allBibleVersions = [...BUILTIN_BIBLES];

    this.highlights = new Map(); // key -> { color, text, refStr, updatedAt }
    this.notes = new Map();      // key -> { book, chapter, verse, refStr, text, updatedAt }

    // Floating bar state
    this.selectedVerseForBar = null;

    // TTS Audio state
    this.ttsPlaying = false;
    this.ttsPaused = false;
    this.ttsCurrentVerse = null;
    this.ttsRate = 1.0;
  }

  async init() {
    // 1. Load data from IndexedDB
    try {
      this.customBibles = await db.getAllCustomBibles();
      this.customCommentaries = await db.getAllCustomCommentaries();
      const hlList = await db.getAllHighlights();
      hlList.forEach(h => this.highlights.set(h.key, h));
      const nList = await db.getAllNotes();
      nList.forEach(n => this.notes.set(n.key, n));
    } catch (e) {
      console.warn("IndexedDB load warning:", e);
    }

    this.allBibleVersions = [...BUILTIN_BIBLES, ...this.customBibles];

    // 2. Load LocalStorage preferences
    this.loadSavedPreferences();

    // 3. Setup Top Selectors
    this.setupBookSelect();
    this.updateChapterSelect();
    this.updateVerseSelect();

    // 4. Event Listeners
    this.setupEventListeners();
    this.setupQuickJumper();
    this.setupFloatingVerseBar();
    this.setupAudioTts();
    this.setupParallelConfig();
    this.setupNoteEditor();
    this.setupShareCard();

    // 5. Initial Render
    this.renderVersionTabs();
    this.renderPassage();
    this.renderLeftPanel();
    this.renderBookIntro();
    this.renderCommentaryTabs();
    this.renderCommentary();
    this.renderSearchVersionSelect();
  }

  // =========================================================
  // Top Navigation Selectors
  // =========================================================
  setupBookSelect() {
    const select = document.getElementById("bookSelect");
    select.innerHTML = "";
    let currentGroup = "";
    let optGroup = null;

    BIBLE_BOOKS.forEach(b => {
      const groupLabel = `${b.testament === "OT" ? "【旧约】" : "【新约】"} ${b.group}`;
      if (groupLabel !== currentGroup) {
        currentGroup = groupLabel;
        optGroup = document.createElement("optgroup");
        optGroup.label = currentGroup;
        select.appendChild(optGroup);
      }

      const opt = document.createElement("option");
      opt.value = b.no;
      opt.textContent = `${b.name} (${b.abbr})`;
      if (b.no === this.currentBook) opt.selected = true;
      optGroup.appendChild(opt);
    });

    select.addEventListener("change", (e) => {
      this.currentBook = parseInt(e.target.value);
      this.currentChapter = 1;
      this.currentVerse = 1;
      this.updateChapterSelect();
      this.updateVerseSelect();
      this.renderPassage();
      this.renderLeftPanel();
      this.renderBookIntro();
      this.renderCommentary();
    });
  }

  updateChapterSelect() {
    const select = document.getElementById("chapterSelect");
    select.innerHTML = "";
    const book = BOOK_MAP.get(this.currentBook);
    const totalChapters = book ? book.chapters : 1;

    for (let c = 1; c <= totalChapters; c++) {
      const opt = document.createElement("option");
      opt.value = c;
      opt.textContent = `第 ${c} 章`;
      if (c === this.currentChapter) opt.selected = true;
      select.appendChild(opt);
    }
  }

  updateVerseSelect() {
    const select = document.getElementById("verseSelect");
    select.innerHTML = "";
    const totalVerses = this.getVersesCountForChapter(this.currentBook, this.currentChapter);

    for (let v = 1; v <= totalVerses; v++) {
      const opt = document.createElement("option");
      opt.value = v;
      opt.textContent = `第 ${v} 节`;
      if (v === this.currentVerse) opt.selected = true;
      select.appendChild(opt);
    }
  }

  getVersesCountForChapter(bookNo, chapNo) {
    // Check if verses exist in CUV
    const cuvMap = this.getVersesMap("CUV");
    let count = 0;
    for (let v = 1; v <= 176; v++) {
      if (cuvMap[`${bookNo}-${chapNo}-${v}`]) count = v;
    }
    if (count > 0) return count;

    // Common landmark chapters
    if (bookNo === 1 && chapNo === 1) return 31;
    if (bookNo === 19 && chapNo === 23) return 6;
    if (bookNo === 43 && chapNo === 1) return 51;
    if (bookNo === 45 && chapNo === 8) return 39;
    if (bookNo === 62 && chapNo === 1) return 10;
    if (bookNo === 63 && chapNo === 1) return 13;
    if (bookNo === 64 && chapNo === 1) return 15;
    if (bookNo === 65 && chapNo === 1) return 25;
    if (bookNo === 66 && chapNo === 21) return 27;
    return 25; // fallback
  }

  renderVersionTabs() {
    const container = document.getElementById("versionTabsContainer");
    container.innerHTML = "";

    this.allBibleVersions.forEach(v => {
      const btn = document.createElement("button");
      btn.className = `version-tab ${this.activeVersion === v.id ? "active" : ""}`;
      btn.dataset.versionId = v.id;
      btn.textContent = v.abbr || v.name;
      btn.title = v.name;
      btn.addEventListener("click", () => {
        this.activeVersion = v.id;
        document.querySelectorAll(".version-tab").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        this.renderPassage();
      });
      container.appendChild(btn);
    });

    // Parallel View Tab
    const parallelBtn = document.createElement("button");
    parallelBtn.className = `version-tab tab-parallel ${this.activeVersion === "PARALLEL" ? "active" : ""}`;
    parallelBtn.innerHTML = `<i class="fa-solid fa-table-columns"></i> 并排比对`;
    parallelBtn.title = "多译本跨列逐节并排比对";
    parallelBtn.addEventListener("click", () => {
      this.activeVersion = "PARALLEL";
      document.querySelectorAll(".version-tab").forEach(b => b.classList.remove("active"));
      parallelBtn.classList.add("active");
      this.renderPassage();
    });
    container.appendChild(parallelBtn);

    // Toggle parallel config button visibility
    const cfgBtn = document.getElementById("btnParallelConfig");
    if (cfgBtn) {
      cfgBtn.style.display = (this.activeVersion === "PARALLEL" || this.layoutMode === 4) ? "inline-flex" : "none";
    }
  }

  // =========================================================
  // Passage & Verses Rendering
  // =========================================================
  renderPassage() {
    const book = BOOK_MAP.get(this.currentBook);
    const titleEl = document.getElementById("currentPassageTitle");
    const metaEl = document.getElementById("currentPassageMeta");
    const container = document.getElementById("versesContainer");

    titleEl.textContent = `${book ? book.name : ""} 第 ${this.currentChapter} 章`;

    const cfgBtn = document.getElementById("btnParallelConfig");
    if (cfgBtn) {
      cfgBtn.style.display = (this.activeVersion === "PARALLEL" || this.layoutMode === 4) ? "inline-flex" : "none";
    }

    // Parallel View Mode
    if (this.activeVersion === "PARALLEL" || this.layoutMode === 4) {
      metaEl.textContent = `多译本并排比对模式 (${this.parallelVersions.join(", ")})`;
      this.renderParallelPassage(container);
      return;
    }

    // Single Version Mode
    const verObj = this.allBibleVersions.find(v => v.id === this.activeVersion);
    metaEl.textContent = verObj ? `${verObj.name} (${verObj.id})` : this.activeVersion;

    const versesMap = this.getVersesMap(this.activeVersion);
    const totalVerses = this.getVersesCountForChapter(this.currentBook, this.currentChapter);

    // Check if verses are present for this chapter
    const firstKey = `${this.currentBook}-${this.currentChapter}-1`;
    const hasLocalVerses = !!versesMap[firstKey];

    container.innerHTML = "";

    if (!hasLocalVerses) {
      // Render Online Chapter Loader Banner
      const card = document.createElement("div");
      card.className = "online-loader-card";
      card.innerHTML = `
        <div class="online-loader-icon"><i class="fa-solid fa-cloud-arrow-down"></i></div>
        <h3>本地暂未缓存【${book ? book.name : ""} 第 ${this.currentChapter} 章】</h3>
        <p>您可以一键在线下载本章经文（自动写入浏览器 IndexedDB 离线数据库，之后随时离线研读）：</p>
        <div class="online-loader-actions">
          <button class="btn btn-primary btn-online-fetch" data-trans="CUNPS"><i class="fa-solid fa-cloud-arrow-down"></i> 在线获取和合本 (简体)</button>
          <button class="btn btn-secondary btn-online-fetch" data-trans="CUNP">和合本 (繁体)</button>
          <button class="btn btn-secondary btn-online-fetch" data-trans="ESV">ESV 英文版</button>
          <button class="btn btn-secondary btn-online-fetch" data-trans="NASB">NASB 英文版</button>
          <button class="btn btn-secondary btn-online-fetch" data-trans="KJV">KJV 英文版</button>
        </div>
        <div class="online-loader-status" id="onlineLoaderStatus"></div>
      `;

      card.querySelectorAll(".btn-online-fetch").forEach(btn => {
        btn.addEventListener("click", () => {
          this.fetchOnlineChapter(btn.dataset.trans, this.currentBook, this.currentChapter);
        });
      });

      container.appendChild(card);
      return;
    }

    for (let v = 1; v <= totalVerses; v++) {
      const key = `${this.currentBook}-${this.currentChapter}-${v}`;
      let text = versesMap[key] || "";
      if (!text) continue;

      const hlObj = this.highlights.get(key);
      const noteObj = this.notes.get(key);

      const row = document.createElement("div");
      row.className = `verse-row ${v === this.currentVerse ? "active" : ""} ${hlObj ? "hl-" + hlObj.color : ""}`;
      row.id = `verse-row-${v}`;
      row.dataset.verseNum = v;

      // Handle Strong's tag formatting if OUS version
      let formattedText = text;
      if (this.activeVersion === "OUS") {
        formattedText = text.replace(/\[(G\d+|H\d+)\]/g, (match, p1) => {
          return `<span class="strong-tag" data-sno="${p1}">${p1}</span>`;
        });
      }

      // Note icon indicator
      const noteBadge = noteObj ? `<span class="note-indicator" title="此节有研经札记: ${escapeHtml(noteObj.text.slice(0, 40))}..."><i class="fa-solid fa-pen-to-square"></i></span>` : "";

      row.innerHTML = `
        <span class="verse-number">${v}</span>
        <div class="verse-content">${formattedText} ${noteBadge}</div>
      `;

      row.addEventListener("click", (e) => {
        if (e.target.classList.contains("strong-tag")) {
          const sno = e.target.dataset.sno;
          this.handleStrongTagClick(sno, e.target);
          return;
        }
        this.setActiveVerse(v);
        this.showFloatingBar(v, row);
      });

      container.appendChild(row);
    }
  }

  renderParallelPassage(container) {
    container.innerHTML = "";
    const compareVersions = this.parallelVersions || ["CUV", "CNV", "CSB", "ESV"];
    const totalVerses = this.getVersesCountForChapter(this.currentBook, this.currentChapter);

    const table = document.createElement("table");
    table.className = "parallel-table";

    // Header
    const thead = document.createElement("thead");
    let headerHtml = "<tr><th style='width:40px;'>节</th>";
    compareVersions.forEach(vid => {
      const verObj = this.allBibleVersions.find(v => v.id === vid);
      headerHtml += `<th>${verObj ? verObj.name : vid}</th>`;
    });
    headerHtml += "</tr>";
    thead.innerHTML = headerHtml;
    table.appendChild(thead);

    // Body
    const tbody = document.createElement("tbody");
    for (let v = 1; v <= totalVerses; v++) {
      const key = `${this.currentBook}-${this.currentChapter}-${v}`;
      const hlObj = this.highlights.get(key);

      const tr = document.createElement("tr");
      tr.className = `${v === this.currentVerse ? "active" : ""} ${hlObj ? "hl-" + hlObj.color : ""}`;
      tr.id = `parallel-row-${v}`;

      let trHtml = `<td><span class="parallel-verse-num">${v}</span></td>`;
      compareVersions.forEach(vid => {
        const vMap = this.getVersesMap(vid);
        const text = vMap[key] || "—";
        trHtml += `<td>${text}</td>`;
      });
      tr.innerHTML = trHtml;
      tr.addEventListener("click", () => {
        this.setActiveVerse(v);
        this.showFloatingBar(v, tr);
      });
      tbody.appendChild(tr);
    }
    table.appendChild(tbody);
    container.appendChild(table);
  }

  getVersesMap(versionId) {
    if (BUILTIN_DATA_VERSES[versionId]) {
      return BUILTIN_DATA_VERSES[versionId];
    }
    const custom = this.customBibles.find(b => b.id === versionId);
    if (custom && custom.verses) {
      return custom.verses;
    }
    return {};
  }

  setActiveVerse(v) {
    this.currentVerse = v;
    const vSel = document.getElementById("verseSelect");
    if (vSel) vSel.value = v;

    document.querySelectorAll(".verse-row").forEach(r => r.classList.remove("active"));
    const activeRow = document.getElementById(`verse-row-${v}`);
    if (activeRow) activeRow.classList.add("active");

    const ind = document.getElementById("activeVerseIndicator");
    if (ind) ind.textContent = `第 ${v} 节`;

    this.highlightCommentaryForVerse(v);
  }

  highlightCommentaryForVerse(v) {
    document.querySelectorAll(".commentary-chunk").forEach(c => c.classList.remove("active-commentary"));
    const target = document.getElementById(`comm-verse-${v}`);
    if (target) {
      target.classList.add("active-commentary");
      target.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
  }

  // =========================================================
  // Online Scripture Fetcher (Bolls.life API + IndexedDB Cache)
  // =========================================================
  async fetchOnlineChapter(trans, bookNo, chapNo) {
    const statusEl = document.getElementById("onlineLoaderStatus");
    if (statusEl) {
      statusEl.className = "online-loader-status";
      statusEl.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> 正在从圣经云端获取【${trans}】数据...`;
    }

    try {
      const url = `https://bolls.life/get-chapter/${trans}/${bookNo}/${chapNo}/`;
      const resp = await fetch(url);
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const data = await resp.json();

      if (!Array.isArray(data) || data.length === 0) {
        throw new Error("未获取到有效经文数据");
      }

      // Map verses
      const targetMap = BUILTIN_DATA_VERSES["CUV"]; // default write target
      data.forEach(item => {
        const v = item.verse;
        let txt = item.text.replace(/<[^>]+>/g, "").trim();
        // remove spaces for Chinese
        if (trans.startsWith("CU") || trans.startsWith("Chi")) {
          txt = txt.replace(/\s+/g, "");
        }
        targetMap[`${bookNo}-${chapNo}-${v}`] = txt;
      });

      // Save to IndexedDB online cache
      await db.saveOnlineCache({
        id: `${trans}-${bookNo}-${chapNo}`,
        translation: trans,
        book: bookNo,
        chapter: chapNo,
        verses: data,
        updatedAt: new Date().toISOString()
      });

      if (statusEl) {
        statusEl.className = "online-loader-status status-msg success";
        statusEl.innerHTML = `✅ 成功下载并缓存 ${data.length} 节经文！已就绪。`;
      }

      showToast(`已成功在线加载并缓存 ${data.length} 节经文！`, "✅");
      setTimeout(() => this.renderPassage(), 400);
    } catch (err) {
      if (statusEl) {
        statusEl.className = "online-loader-status status-msg error";
        statusEl.innerHTML = `获取失败: ${err.message}。请检查网络或上传本地文件。`;
      }
    }
  }

  // =========================================================
  // Left Panel Rendering (Outlines, Cross-Refs, Charts, Highlights, Notes)
  // =========================================================
  renderLeftPanel() {
    const container = document.getElementById("leftPanelBody");
    container.innerHTML = "";

    const book = BOOK_MAP.get(this.currentBook);
    const bookKey = String(this.currentBook);
    const bookOutlines = BUILTIN_BOOK_OUTLINES[bookKey] || BUILTIN_BOOK_OUTLINES["64"];

    if (this.activeLeftTab === "studyOutline" || this.activeLeftTab === "structOutline") {
      const outlineData = (bookOutlines && bookOutlines[this.activeLeftTab]) ? bookOutlines[this.activeLeftTab] : [];

      const grp = document.createElement("div");
      grp.className = "outline-group";
      grp.innerHTML = `<div class="outline-group-title"><i class="fa-solid fa-layer-group"></i> 《${book ? book.name : ""}》${this.activeLeftTab === "studyOutline" ? "研读大纲" : "结构分析大纲"}</div>`;

      if (outlineData.length === 0) {
        grp.innerHTML += `<div class="text-secondary" style="padding:10px;">当前书卷暂无内置大纲，可导入或切换至创世记、诗篇、约翰福音、罗马书、约翰三书等查看。</div>`;
      }

      outlineData.forEach(item => {
        const div = document.createElement("div");
        div.className = `outline-item depth-${item.depth}`;
        div.innerHTML = `
          <span>${item.title}</span>
          ${item.verses ? `<span class="outline-verse-badge">${item.verses[0]}-${item.verses[item.verses.length-1]}节</span>` : ""}
        `;
        div.addEventListener("click", () => {
          if (item.verses && item.verses.length > 0) {
            this.setActiveVerse(item.verses[0]);
            const targetRow = document.getElementById(`verse-row-${item.verses[0]}`);
            if (targetRow) targetRow.scrollIntoView({ behavior: "smooth", block: "center" });
          }
        });
        grp.appendChild(div);
      });
      container.appendChild(grp);
    }
    else if (this.activeLeftTab === "crossRef") {
      const refs = (bookOutlines && bookOutlines.crossRef) ? bookOutlines.crossRef : [];
      container.innerHTML = `<div class="outline-group-title"><i class="fa-solid fa-link"></i> 《${book ? book.name : ""}》串珠平行经文 (TSK)</div>`;
      if (refs.length === 0) {
        container.innerHTML += `<div class="text-secondary" style="padding:10px;">暂无该章节预设串珠经文。</div>`;
      }
      refs.forEach(r => {
        const card = document.createElement("div");
        card.className = "cross-ref-card";
        card.innerHTML = `
          <div class="cross-ref-header">第 ${r.verse} 节 关联经节: ${r.ref}</div>
          <div class="cross-ref-text">${r.note}</div>
        `;
        card.addEventListener("click", () => this.setActiveVerse(r.verse));
        container.appendChild(card);
      });
    }
    else if (this.activeLeftTab === "backgroundCharts") {
      const charts = (bookOutlines && bookOutlines.backgroundCharts) ? bookOutlines.backgroundCharts : [];
      container.innerHTML = `<div class="outline-group-title"><i class="fa-solid fa-chart-pie"></i> 《${book ? book.name : ""}》图表、年表与历史地理</div>`;
      if (charts.length === 0) {
        container.innerHTML += `<div class="text-secondary" style="padding:10px;">暂无该章节预设历史背景图表。</div>`;
      }
      charts.forEach(c => {
        const card = document.createElement("div");
        card.className = "chart-item";
        card.innerHTML = `
          <div class="chart-title">${c.title}</div>
          <div class="chart-desc">${c.desc}</div>
        `;
        container.appendChild(card);
      });
    }
    else if (this.activeLeftTab === "myHighlights") {
      // My Highlights
      container.innerHTML = `<div class="outline-group-title"><i class="fa-solid fa-highlighter"></i> 我的高亮标注 (${this.highlights.size} 条)</div>`;
      if (this.highlights.size === 0) {
        container.innerHTML += `<div class="text-secondary" style="padding:10px;">暂无经文高亮。点击经文行即可使用 5 种彩色荧光笔标记经文。</div>`;
        return;
      }

      this.highlights.forEach((h, key) => {
        const [bNo, cNo, vNo] = key.split("-").map(Number);
        const bObj = BOOK_MAP.get(bNo);
        const card = document.createElement("div");
        card.className = "highlight-item-card";
        card.innerHTML = `
          <div class="hl-card-header">
            <span style="font-weight:700; font-size:12px; color:var(--primary);">${bObj ? bObj.name : ""} ${cNo}:${vNo}</span>
            <span class="hl-badge-pill hl-pill-${h.color}">${this.getColorLabel(h.color)}</span>
          </div>
          <div style="font-size:12px; color:var(--text-secondary); line-height:1.4;">${escapeHtml(h.text || "")}</div>
        `;
        card.addEventListener("click", () => {
          this.jumpTo(bNo, cNo, vNo);
        });
        container.appendChild(card);
      });
    }
    else if (this.activeLeftTab === "myNotes") {
      // My Notes
      container.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
          <div class="outline-group-title" style="margin:0;"><i class="fa-solid fa-pen-to-square"></i> 研经札记 (${this.notes.size} 篇)</div>
          <button class="btn btn-xs btn-ghost" id="btnExportNotes"><i class="fa-solid fa-download"></i> 导出</button>
        </div>
      `;

      const expBtn = container.querySelector("#btnExportNotes");
      if (expBtn) {
        expBtn.addEventListener("click", () => this.exportNotesAsMarkdown());
      }

      if (this.notes.size === 0) {
        container.innerHTML += `<div class="text-secondary" style="padding:10px;">暂无研经札记。点击经文行并在悬浮条中点击「札记」即可记录心得体会。</div>`;
        return;
      }

      this.notes.forEach((n, key) => {
        const card = document.createElement("div");
        card.className = "note-item-card";
        card.innerHTML = `
          <div class="note-card-header">
            <span style="font-weight:700; font-size:12px; color:var(--primary);">${escapeHtml(n.refStr || key)}</span>
            <span style="font-size:10px; color:var(--text-muted);">${(n.updatedAt || "").slice(0, 10)}</span>
          </div>
          <div class="note-card-text">${escapeHtml(n.text || "")}</div>
        `;
        card.addEventListener("click", () => {
          this.jumpTo(n.book, n.chapter, n.verse);
          this.openNoteEditor(n.verse);
        });
        container.appendChild(card);
      });
    }
  }

  getColorLabel(color) {
    const map = {
      yellow: "灵修感悟",
      green: "神的应许",
      blue: "纯正真理",
      red: "恩典救赎",
      purple: "诫命警勉"
    };
    return map[color] || "高亮";
  }

  // =========================================================
  // Right Panel Rendering (Book Introductions & Commentaries)
  // =========================================================
  renderBookIntro() {
    const bookKey = String(this.currentBook);
    const introData = BUILTIN_BOOK_INTROS[bookKey] || BUILTIN_BOOK_INTROS["64"];
    const badgeEl = document.getElementById("introAuthorBadge");
    const container = document.getElementById("introContainer");

    badgeEl.textContent = introData.author ? introData.author.split("(")[0].trim() : "圣经学者";
    container.innerHTML = `
      ${introData.content || ""}
      <div style="margin-top:10px; font-size:11.5px; color:var(--text-muted);">
        <div><strong>成书时间</strong>: ${introData.date || "古代"}</div>
        <div><strong>核心主题</strong>: ${introData.theme || "神圣启示"}</div>
      </div>
    `;
  }

  renderCommentaryTabs() {
    const container = document.getElementById("commentaryTabsContainer");
    container.innerHTML = "";

    const builtinComms = [
      { id: "burdick", name: "伯迪克注释", author: "唐纳德·伯迪克" },
      { id: "believers", name: "信徒圣经注释", author: "威廉·麦克唐纳" },
      { id: "macarthur", name: "讲道与解经", author: "约翰·麦克阿瑟" }
    ];

    builtinComms.forEach(c => {
      const btn = document.createElement("button");
      btn.className = `tab-btn ${this.activeCommId === c.id ? "active" : ""}`;
      btn.dataset.commId = c.id;
      btn.textContent = c.name;
      btn.title = `作者: ${c.author}`;
      btn.addEventListener("click", () => {
        this.activeCommId = c.id;
        this.renderCommentaryTabs();
        this.renderCommentary();
      });
      container.appendChild(btn);
    });

    this.customCommentaries.forEach(c => {
      const btn = document.createElement("button");
      btn.className = `tab-btn ${this.activeCommId === c.id ? "active" : ""}`;
      btn.dataset.commId = c.id;
      btn.textContent = c.title || c.id;
      btn.title = `作者: ${c.author || "自定义"}`;
      btn.addEventListener("click", () => {
        this.activeCommId = c.id;
        this.renderCommentaryTabs();
        this.renderCommentary();
      });
      container.appendChild(btn);
    });
  }

  renderCommentary() {
    const container = document.getElementById("commentaryContainer");
    container.innerHTML = "";

    const bookKey = String(this.currentBook);
    const book = BOOK_MAP.get(this.currentBook);
    let versesDict = {};

    // Check builtin commentary
    if (BUILTIN_BOOK_COMMENTARIES[this.activeCommId]) {
      const commEntry = BUILTIN_BOOK_COMMENTARIES[this.activeCommId];
      if (commEntry.books && commEntry.books[bookKey]) {
        versesDict = commEntry.books[bookKey];
      } else if (commEntry.books && commEntry.books["64"] && this.currentBook === 64) {
        versesDict = commEntry.books["64"];
      }
    } else {
      const custom = this.customCommentaries.find(c => c.id === this.activeCommId);
      if (custom && custom.verses) {
        versesDict = custom.verses;
      }
    }

    const totalVerses = this.getVersesCountForChapter(this.currentBook, this.currentChapter);
    let renderedCount = 0;

    for (let v = 1; v <= totalVerses; v++) {
      const commText = versesDict[String(v)];
      if (!commText) continue;

      renderedCount++;
      const chunk = document.createElement("div");
      chunk.className = `commentary-chunk ${v === this.currentVerse ? "active-commentary" : ""}`;
      chunk.id = `comm-verse-${v}`;
      chunk.innerHTML = `
        <div class="commentary-header"><i class="fa-solid fa-bookmark"></i> ${book ? book.name : ""} ${this.currentChapter}:${v} 节解经</div>
        <div class="commentary-text">${commText}</div>
      `;
      chunk.addEventListener("click", () => this.setActiveVerse(v));
      container.appendChild(chunk);
    }

    if (renderedCount === 0) {
      container.innerHTML = `
        <div class="text-secondary" style="padding:14px; line-height:1.6;">
          当前书卷本章节在【${this.activeCommId}】中暂无逐节释经条目。<br>
          您可切换至创世记 1、诗篇 23、约翰福音 1、罗马书 8、约翰三书 1 查看完整释经演示，或点击右上角「管理与导入」上传您自己的释经专著。
        </div>
      `;
    }
  }

  // =========================================================
  // Quick Jumper (Command Palette Cmd+K)
  // =========================================================
  setupQuickJumper() {
    const modal = document.getElementById("quickJumperModal");
    const input = document.getElementById("quickJumperInput");
    const resultsContainer = document.getElementById("quickJumperResults");

    const openJumper = () => {
      modal.style.display = "flex";
      input.value = "";
      input.focus();
      this.renderQuickJumperResults("");
    };

    const closeJumper = () => {
      modal.style.display = "none";
    };

    const triggerBtn = document.getElementById("btnOpenQuickJumper");
    if (triggerBtn) triggerBtn.addEventListener("click", openJumper);

    const closeEsc = document.getElementById("btnCloseQuickJumper");
    if (closeEsc) closeEsc.addEventListener("click", closeJumper);

    modal.addEventListener("click", (e) => {
      if (e.target === modal) closeJumper();
    });

    input.addEventListener("input", (e) => {
      this.renderQuickJumperResults(e.target.value.trim());
    });

    input.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        closeJumper();
      } else if (e.key === "Enter") {
        const first = resultsContainer.querySelector(".quick-jumper-item");
        if (first) first.click();
      }
    });

    window.addEventListener("keydown", (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        openJumper();
      }
    });
  }

  renderQuickJumperResults(query) {
    const container = document.getElementById("quickJumperResults");
    container.innerHTML = "";

    let parsed = this.parseScriptureReference(query);

    let candidates = [];
    if (parsed) {
      candidates.push(parsed);
    }

    // Also match books by name
    const qLower = query.toLowerCase();
    BIBLE_BOOKS.forEach(b => {
      if (!query || b.name.includes(query) || b.abbr.includes(query) || b.english.toLowerCase().includes(qLower) || (b.enAbbr && b.enAbbr.includes(qLower))) {
        candidates.push({ bookNo: b.no, chapter: 1, verse: 1 });
      }
    });

    // Deduplicate & limit to 8
    const seen = new Set();
    const finalCandidates = [];
    for (const c of candidates) {
      const k = `${c.bookNo}-${c.chapter}-${c.verse}`;
      if (!seen.has(k)) {
        seen.add(k);
        finalCandidates.push(c);
      }
      if (finalCandidates.length >= 8) break;
    }

    if (finalCandidates.length === 0) {
      container.innerHTML = `<div style="padding:16px; text-align:center; color:var(--text-muted); font-size:13px;">未找到匹配的书卷经文。试着输入：创 1、诗 23:1、约 3:16、罗 8:28、Jn 1:1</div>`;
      return;
    }

    finalCandidates.forEach((c, idx) => {
      const bObj = BOOK_MAP.get(c.bookNo);
      const item = document.createElement("div");
      item.className = `quick-jumper-item ${idx === 0 ? "selected" : ""}`;
      item.innerHTML = `
        <div class="quick-jumper-title">
          <i class="fa-solid fa-book-bible" style="color:var(--primary); font-size:13px;"></i>
          <span>${bObj ? bObj.name : ""} 第 ${c.chapter} 章 ${c.verse ? `第 ${c.verse} 节` : ""}</span>
        </div>
        <div class="quick-jumper-meta">${bObj ? bObj.english : ""} · ${bObj ? bObj.group : ""}</div>
      `;
      item.addEventListener("click", () => {
        document.getElementById("quickJumperModal").style.display = "none";
        this.jumpTo(c.bookNo, c.chapter, c.verse || 1);
      });
      container.appendChild(item);
    });
  }

  parseScriptureReference(input) {
    if (!input) return null;
    const clean = input.trim();
    // Match: [Book] [Chapter]:[Verse] or [Book] [Chapter]
    const m = clean.match(/^([\u4e00-\u9fa5a-zA-Z0-9]+)\s*(\d+)(?:[:：](\d+))?$/);
    if (!m) {
      // Just book abbreviation
      const bNo = BOOK_NAME_MAP.get(clean.toLowerCase());
      if (bNo) return { bookNo: bNo, chapter: 1, verse: 1 };
      return null;
    }

    const bookPart = m[1].toLowerCase();
    const chap = parseInt(m[2]);
    const verse = m[3] ? parseInt(m[3]) : 1;

    const bNo = BOOK_NAME_MAP.get(bookPart);
    if (!bNo) return null;
    const bObj = BOOK_MAP.get(bNo);
    if (!bObj) return null;

    const validChap = Math.min(bObj.chapters, Math.max(1, chap));
    return { bookNo: bNo, chapter: validChap, verse: verse };
  }

  jumpTo(bookNo, chapNo, verseNo) {
    this.currentBook = bookNo;
    this.currentChapter = chapNo;
    this.currentVerse = verseNo || 1;

    document.getElementById("bookSelect").value = this.currentBook;
    this.updateChapterSelect();
    document.getElementById("chapterSelect").value = this.currentChapter;
    this.updateVerseSelect();
    document.getElementById("verseSelect").value = this.currentVerse;

    this.renderPassage();
    this.renderLeftPanel();
    this.renderBookIntro();
    this.renderCommentary();

    setTimeout(() => {
      const row = document.getElementById(`verse-row-${this.currentVerse}`) || document.getElementById(`parallel-row-${this.currentVerse}`);
      if (row) row.scrollIntoView({ behavior: "smooth", block: "center" });
    }, 150);
  }

  // =========================================================
  // Floating Verse Action Bar (Highlighting, Notes, Copy, Speak, Card)
  // =========================================================
  setupFloatingVerseBar() {
    const bar = document.getElementById("verseFloatingBar");

    // Color pickers
    bar.querySelectorAll(".btn-hl-color").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        const color = btn.dataset.color;
        if (this.selectedVerseForBar) {
          if (color === "none") {
            this.removeHighlight(this.selectedVerseForBar);
          } else {
            this.setHighlight(this.selectedVerseForBar, color);
          }
        }
        bar.style.display = "none";
      });
    });

    // Note button
    document.getElementById("btnBarNote").addEventListener("click", (e) => {
      e.stopPropagation();
      bar.style.display = "none";
      if (this.selectedVerseForBar) this.openNoteEditor(this.selectedVerseForBar);
    });

    // Copy button
    document.getElementById("btnBarCopy").addEventListener("click", (e) => {
      e.stopPropagation();
      bar.style.display = "none";
      if (this.selectedVerseForBar) this.copyVerseCitation(this.selectedVerseForBar);
    });

    // Speak button
    document.getElementById("btnBarSpeak").addEventListener("click", (e) => {
      e.stopPropagation();
      bar.style.display = "none";
      if (this.selectedVerseForBar) this.playTtsVerse(this.selectedVerseForBar);
    });

    // Share Card button
    document.getElementById("btnBarCard").addEventListener("click", (e) => {
      e.stopPropagation();
      bar.style.display = "none";
      if (this.selectedVerseForBar) this.openShareCardModal(this.selectedVerseForBar);
    });

    // Click outside hides bar
    document.addEventListener("click", (e) => {
      if (!bar.contains(e.target) && !e.target.closest(".verse-row") && !e.target.closest(".parallel-table tr")) {
        bar.style.display = "none";
      }
    });
  }

  showFloatingBar(vNum, targetEl) {
    this.selectedVerseForBar = vNum;
    const bar = document.getElementById("verseFloatingBar");
    bar.style.display = "flex";

    const rect = targetEl.getBoundingClientRect();
    const barHeight = 36;
    let top = rect.top - barHeight - 6;
    if (top < 50) top = rect.bottom + 6; // flip below if offscreen

    bar.style.top = `${top + window.scrollY}px`;
    bar.style.left = `${Math.max(10, rect.left + 20)}px`;
  }

  async setHighlight(vNum, color) {
    const key = `${this.currentBook}-${this.currentChapter}-${vNum}`;
    const vMap = this.getVersesMap(this.activeVersion);
    const text = vMap[key] || "";
    const bObj = BOOK_MAP.get(this.currentBook);
    const refStr = `${bObj ? bObj.name : ""} ${this.currentChapter}:${vNum}`;

    const hlObj = {
      key: key,
      color: color,
      text: text,
      refStr: refStr,
      updatedAt: new Date().toISOString()
    };

    this.highlights.set(key, hlObj);
    await db.saveHighlight(hlObj);

    showToast(`已标记【${this.getColorLabel(color)}】高亮！`, "🖍️");
    this.renderPassage();
    if (this.activeLeftTab === "myHighlights") this.renderLeftPanel();
  }

  async removeHighlight(vNum) {
    const key = `${this.currentBook}-${this.currentChapter}-${vNum}`;
    this.highlights.delete(key);
    await db.deleteHighlight(key);
    showToast("已清除经文高亮！", "⚪");
    this.renderPassage();
    if (this.activeLeftTab === "myHighlights") this.renderLeftPanel();
  }

  // =========================================================
  // Note Editor
  // =========================================================
  setupNoteEditor() {
    const modal = document.getElementById("noteEditorModal");
    const closeBtn = document.getElementById("btnCloseNoteModal");
    const cancelBtn = document.getElementById("btnCancelNote");
    const saveBtn = document.getElementById("btnSaveNote");
    const delBtn = document.getElementById("btnDeleteNote");

    const closeModal = () => { modal.style.display = "none"; };
    if (closeBtn) closeBtn.addEventListener("click", closeModal);
    if (cancelBtn) cancelBtn.addEventListener("click", closeModal);

    modal.addEventListener("click", (e) => {
      if (e.target === modal) closeModal();
    });

    saveBtn.addEventListener("click", async () => {
      const text = document.getElementById("noteTextInput").value.trim();
      if (!text) {
        alert("请输入札记内容！");
        return;
      }
      const vNum = this.selectedVerseForBar || this.currentVerse;
      const key = `${this.currentBook}-${this.currentChapter}-${vNum}`;
      const bObj = BOOK_MAP.get(this.currentBook);
      const refStr = `${bObj ? bObj.name : ""} ${this.currentChapter}:${vNum}`;

      const noteObj = {
        key: key,
        book: this.currentBook,
        chapter: this.currentChapter,
        verse: vNum,
        refStr: refStr,
        text: text,
        updatedAt: new Date().toISOString()
      };

      this.notes.set(key, noteObj);
      await db.saveNote(noteObj);
      showToast("研经札记保存成功！", "📝");
      closeModal();
      this.renderPassage();
      if (this.activeLeftTab === "myNotes") this.renderLeftPanel();
    });

    delBtn.addEventListener("click", async () => {
      const vNum = this.selectedVerseForBar || this.currentVerse;
      const key = `${this.currentBook}-${this.currentChapter}-${vNum}`;
      if (confirm("确定要删除这篇研经札记吗？")) {
        this.notes.delete(key);
        await db.deleteNote(key);
        showToast("札记已删除", "🗑️");
        closeModal();
        this.renderPassage();
        if (this.activeLeftTab === "myNotes") this.renderLeftPanel();
      }
    });
  }

  openNoteEditor(vNum) {
    const modal = document.getElementById("noteEditorModal");
    const key = `${this.currentBook}-${this.currentChapter}-${vNum}`;
    const bObj = BOOK_MAP.get(this.currentBook);
    const refStr = `${bObj ? bObj.name : ""} ${this.currentChapter}:${vNum}`;

    document.getElementById("noteModalTitle").textContent = `研经札记 — ${refStr}`;

    const vMap = this.getVersesMap(this.activeVersion);
    const text = vMap[key] || "";
    document.getElementById("noteModalVerseText").textContent = `【${refStr}】${text}`;

    const existing = this.notes.get(key);
    document.getElementById("noteTextInput").value = existing ? existing.text : "";
    document.getElementById("btnDeleteNote").style.display = existing ? "inline-flex" : "none";

    modal.style.display = "flex";
    document.getElementById("noteTextInput").focus();
  }

  exportNotesAsMarkdown() {
    if (this.notes.size === 0) {
      alert("当前没有可导出的研经札记。");
      return;
    }
    let md = `# 个人圣经研读札记与灵修日志\n\n*导出时间: ${new Date().toLocaleString()}*\n\n---\n\n`;
    this.notes.forEach(n => {
      md += `### ${n.refStr || ""} (${(n.updatedAt||"").slice(0,10)})\n\n${n.text}\n\n---\n\n`;
    });

    const blob = new Blob([md], { type: "text/markdown;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `bible-notes-${new Date().toISOString().slice(0, 10)}.md`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    showToast("所有札记已成功导出为 Markdown 文件！", "📥");
  }

  // =========================================================
  // Citation Copy & Share Card Generator
  // =========================================================
  copyVerseCitation(vNum) {
    const key = `${this.currentBook}-${this.currentChapter}-${vNum}`;
    const vMap = this.getVersesMap(this.activeVersion);
    const text = vMap[key] || "";
    const bObj = BOOK_MAP.get(this.currentBook);
    const verObj = this.allBibleVersions.find(v => v.id === this.activeVersion);
    const citation = `【${bObj ? bObj.name : ""} ${this.currentChapter}:${vNum}】${text}（${verObj ? verObj.name : this.activeVersion}）`;

    navigator.clipboard.writeText(citation).then(() => {
      showToast("经文引用已复制到剪贴板！", "📋");
    });
  }

  setupShareCard() {
    const modal = document.getElementById("scriptureCardModal");
    const closeBtn = document.getElementById("btnCloseCardModal");
    const copyTxtBtn = document.getElementById("btnCopyCardText");
    const copyMdBtn = document.getElementById("btnCopyCardMarkdown");

    const closeModal = () => { modal.style.display = "none"; };
    if (closeBtn) closeBtn.addEventListener("click", closeModal);

    modal.addEventListener("click", (e) => {
      if (e.target === modal) closeModal();
    });

    // Theme selector
    modal.querySelectorAll(".card-style-btn").forEach(btn => {
      btn.addEventListener("click", () => {
        modal.querySelectorAll(".card-style-btn").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        const canvas = document.getElementById("scriptureCardCanvas");
        canvas.className = `scripture-card-canvas ${btn.dataset.cardTheme}`;
      });
    });

    copyTxtBtn.addEventListener("click", () => {
      const vNum = this.selectedVerseForBar || this.currentVerse;
      this.copyVerseCitation(vNum);
    });

    copyMdBtn.addEventListener("click", () => {
      const vNum = this.selectedVerseForBar || this.currentVerse;
      const key = `${this.currentBook}-${this.currentChapter}-${vNum}`;
      const vMap = this.getVersesMap(this.activeVersion);
      const text = vMap[key] || "";
      const bObj = BOOK_MAP.get(this.currentBook);
      const md = `> ${text}\n> \n> ——《${bObj ? bObj.name : ""}》${this.currentChapter}:${vNum}`;
      navigator.clipboard.writeText(md).then(() => {
        showToast("Markdown 格式引用已复制！", "📋");
      });
    });
  }

  openShareCardModal(vNum) {
    const modal = document.getElementById("scriptureCardModal");
    const key = `${this.currentBook}-${this.currentChapter}-${vNum}`;
    const vMap = this.getVersesMap(this.activeVersion);
    const text = vMap[key] || "";
    const bObj = BOOK_MAP.get(this.currentBook);
    const verObj = this.allBibleVersions.find(v => v.id === this.activeVersion);

    document.getElementById("cardVerseBody").textContent = text;
    document.getElementById("cardVerseRef").textContent = `—— ${bObj ? bObj.name : ""} ${this.currentChapter}:${vNum} · ${verObj ? verObj.name : this.activeVersion}`;

    modal.style.display = "flex";
  }

  // =========================================================
  // Parallel Bible Configurator
  // =========================================================
  setupParallelConfig() {
    const modal = document.getElementById("parallelConfigModal");
    const openBtn = document.getElementById("btnParallelConfig");
    const closeBtn = document.getElementById("btnCloseParallelModal");
    const cancelBtn = document.getElementById("btnCancelParallelConfig");
    const saveBtn = document.getElementById("btnSaveParallelConfig");

    const openModal = () => {
      this.renderParallelOptions();
      modal.style.display = "flex";
    };

    const closeModal = () => { modal.style.display = "none"; };

    if (openBtn) openBtn.addEventListener("click", openModal);
    if (closeBtn) closeBtn.addEventListener("click", closeModal);
    if (cancelBtn) cancelBtn.addEventListener("click", closeModal);

    modal.addEventListener("click", (e) => {
      if (e.target === modal) closeModal();
    });

    saveBtn.addEventListener("click", () => {
      const selected = [];
      modal.querySelectorAll("input[type=checkbox]:checked").forEach(cb => {
        selected.push(cb.value);
      });
      if (selected.length === 0) {
        alert("请至少选择一个比对译本！");
        return;
      }
      this.parallelVersions = selected;
      localStorage.setItem("bible_parallel_versions", JSON.stringify(selected));
      showToast("多译本并排配置已更新！", "⚙️");
      closeModal();
      this.renderPassage();
    });
  }

  renderParallelOptions() {
    const list = document.getElementById("parallelOptionsList");
    list.innerHTML = "";

    this.allBibleVersions.forEach(v => {
      const row = document.createElement("label");
      row.className = "parallel-opt-row";
      const isChecked = this.parallelVersions.includes(v.id);
      row.innerHTML = `
        <input type="checkbox" value="${v.id}" ${isChecked ? "checked" : ""}>
        <span style="font-weight:600; font-size:13px;">${v.name}</span>
        <span class="badge" style="font-size:11px; margin-left:auto; color:var(--text-muted);">${v.id}</span>
      `;
      list.appendChild(row);
    });
  }

  // =========================================================
  // Web Speech API TTS Audio Bible Reader
  // =========================================================
  setupAudioTts() {
    const playBtn = document.getElementById("btnTtsPlayPause");
    const stopBtn = document.getElementById("btnTtsStop");
    const rateSelect = document.getElementById("ttsRateSelect");

    if (rateSelect) {
      rateSelect.addEventListener("change", (e) => {
        this.ttsRate = parseFloat(e.target.value);
      });
    }

    if (playBtn) {
      playBtn.addEventListener("click", () => this.toggleTts());
    }

    if (stopBtn) {
      stopBtn.addEventListener("click", () => this.stopTts());
    }
  }

  toggleTts() {
    if (!("speechSynthesis" in window)) {
      alert("您的浏览器不支持语音朗读 (Web Speech API)。");
      return;
    }

    if (window.speechSynthesis.speaking) {
      if (window.speechSynthesis.paused) {
        window.speechSynthesis.resume();
        this.updateTtsUi(true, false);
      } else {
        window.speechSynthesis.pause();
        this.updateTtsUi(false, true);
      }
      return;
    }

    this.startTtsChapter();
  }

  startTtsChapter() {
    window.speechSynthesis.cancel();
    const totalVerses = this.getVersesCountForChapter(this.currentBook, this.currentChapter);
    let startVerse = this.currentVerse || 1;
    if (startVerse > totalVerses) startVerse = 1;

    this.ttsPlaying = true;
    this.updateTtsUi(true, false);
    this.playTtsVerse(startVerse);
  }

  playTtsVerse(vNum) {
    window.speechSynthesis.cancel();
    const key = `${this.currentBook}-${this.currentChapter}-${vNum}`;
    const vMap = this.getVersesMap(this.activeVersion);
    let text = vMap[key] || "";
    if (!text) {
      this.stopTts();
      return;
    }

    // Strip Strong tags [G...] or [H...]
    text = text.replace(/\[(G\d+|H\d+)\]/g, "");

    const isEnglish = (this.activeVersion === "ESV" || this.activeVersion === "NASB");
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = isEnglish ? "en-US" : "zh-CN";
    utterance.rate = this.ttsRate || 1.0;

    this.ttsCurrentVerse = vNum;
    this.setActiveVerse(vNum);

    // Glowing animation
    document.querySelectorAll(".verse-row").forEach(r => r.classList.remove("speaking-pulse"));
    const activeRow = document.getElementById(`verse-row-${vNum}`);
    if (activeRow) {
      activeRow.classList.add("speaking-pulse");
      activeRow.scrollIntoView({ behavior: "smooth", block: "center" });
    }

    const badge = document.getElementById("ttsStatusBadge");
    const badgeText = document.getElementById("ttsStatusText");
    if (badge && badgeText) {
      badge.style.display = "inline-flex";
      badgeText.textContent = `第 ${vNum} 节`;
    }

    utterance.onend = () => {
      if (!this.ttsPlaying) return;
      const totalVerses = this.getVersesCountForChapter(this.currentBook, this.currentChapter);
      if (vNum < totalVerses) {
        this.playTtsVerse(vNum + 1);
      } else {
        this.stopTts();
        showToast("本章经文朗读完毕！", "🎉");
      }
    };

    utterance.onerror = (e) => {
      console.warn("TTS error:", e);
      this.stopTts();
    };

    window.speechSynthesis.speak(utterance);
    this.updateTtsUi(true, false);
  }

  stopTts() {
    this.ttsPlaying = false;
    window.speechSynthesis.cancel();
    document.querySelectorAll(".verse-row").forEach(r => r.classList.remove("speaking-pulse"));
    this.updateTtsUi(false, false);
    const badge = document.getElementById("ttsStatusBadge");
    if (badge) badge.style.display = "none";
  }

  updateTtsUi(isPlaying, isPaused) {
    const icon = document.getElementById("ttsPlayIcon");
    const text = document.getElementById("ttsBtnText");
    const stopBtn = document.getElementById("btnTtsStop");

    if (isPlaying) {
      if (icon) icon.className = "fa-solid fa-pause";
      if (text) text.textContent = "暂停";
      if (stopBtn) stopBtn.style.display = "inline-flex";
    } else if (isPaused) {
      if (icon) icon.className = "fa-solid fa-play";
      if (text) text.textContent = "继续";
      if (stopBtn) stopBtn.style.display = "inline-flex";
    } else {
      if (icon) icon.className = "fa-solid fa-play";
      if (text) text.textContent = "朗读";
      if (stopBtn) stopBtn.style.display = "none";
    }
  }

  // =========================================================
  // Strong's Concordance Tags Click & Lexicon Drawer
  // =========================================================
  handleStrongTagClick(sno, targetEl) {
    const entry = BUILTIN_STRONGS[sno] || {
      id: sno,
      lemma: sno.startsWith("H") ? "עִבְרִית" : "Ἑλληνικά",
      translit: sno,
      pronounce: "—",
      pos: sno.startsWith("H") ? "希伯来原文" : "希腊原文",
      origin: "圣经原文字根",
      def: `【史特郎原文编号 ${sno}】可在下方词典抽屉中查看该原文字词的全文经文反查与详细词源。`,
      occurrences: 1
    };

    const popover = document.getElementById("strongPopover");
    document.getElementById("popoverStrongBadge").textContent = entry.id;
    document.getElementById("popoverOriginalWord").textContent = `${entry.lemma} (${entry.translit || ""})`;

    document.getElementById("popoverBody").innerHTML = `
      <div style="margin-bottom:6px;"><strong>词性</strong>: ${entry.pos || ""} · <strong>发音</strong>: <em>${entry.pronounce || ""}</em></div>
      <div style="margin-bottom:6px;"><strong>词源</strong>: ${entry.origin || "基本字根"}</div>
      <div style="line-height:1.5;">${entry.def}</div>
      <div style="margin-top:6px; font-size:11px; color:var(--text-muted);">全本圣经出现约 <strong>${entry.occurrences}</strong> 次</div>
    `;

    popover.style.display = "block";
    const rect = targetEl.getBoundingClientRect();
    let top = rect.bottom + 8;
    let left = rect.left;
    if (left + 320 > window.innerWidth) left = window.innerWidth - 330;
    popover.style.top = `${top + window.scrollY}px`;
    popover.style.left = `${Math.max(10, left)}px`;

    document.getElementById("btnPopoverDetails").onclick = () => {
      popover.style.display = "none";
      this.openLexiconInDrawer(entry);
    };

    document.getElementById("btnPopoverSearch").onclick = () => {
      popover.style.display = "none";
      this.searchStrongInBible(sno);
    };
  }

  openLexiconInDrawer(entry) {
    const drawer = document.getElementById("bottomDrawer");
    drawer.classList.remove("collapsed");

    document.querySelectorAll(".drawer-tab-btn").forEach(b => b.classList.remove("active"));
    document.querySelectorAll(".drawer-view").forEach(v => v.classList.remove("active"));

    const lexTab = document.querySelector('[data-drawer-tab="lexicon"]');
    const lexView = document.getElementById("drawerViewLexicon");
    if (lexTab) lexTab.classList.add("active");
    if (lexView) lexView.classList.add("active");

    document.getElementById("lexiconContent").innerHTML = `
      <div class="lexicon-card">
        <div class="lexicon-top">
          <span class="lexicon-badge">${entry.id}</span>
          <span class="lexicon-lemma">${entry.lemma}</span>
          <span class="lexicon-translit">${entry.translit || ""} [${entry.pronounce || ""}]</span>
          <span style="font-size:12px; color:var(--text-muted); margin-left:auto;">${entry.pos || ""}</span>
        </div>
        <div style="font-size:13px; color:var(--text-secondary); margin-bottom:8px;">
          <strong>词源考究</strong>: ${entry.origin || "希腊文/希伯来文字根"} · <strong>出处频次</strong>: 全书出现约 ${entry.occurrences} 次
        </div>
        <div class="lexicon-def">${entry.def}</div>
        <div style="margin-top:14px;">
          <button class="btn btn-sm btn-primary" onclick="window.workbenchApp.searchStrongInBible('${entry.id}')">
            <i class="fa-solid fa-magnifying-glass"></i> 在圣经中反查包含此原文的所有经节
          </button>
        </div>
      </div>
    `;
  }

  searchStrongInBible(sno) {
    const drawer = document.getElementById("bottomDrawer");
    drawer.classList.remove("collapsed");

    document.querySelectorAll(".drawer-tab-btn").forEach(b => b.classList.remove("active"));
    document.querySelectorAll(".drawer-view").forEach(v => v.classList.remove("active"));

    const sTab = document.querySelector('[data-drawer-tab="search"]');
    const sView = document.getElementById("drawerViewSearch");
    if (sTab) sTab.classList.add("active");
    if (sView) sView.classList.add("active");

    document.getElementById("searchInput").value = sno;
    document.getElementById("searchVersionSelect").value = "OUS";
    this.executeSearch(sno, "OUS");
  }

  // =========================================================
  // Full Text Search Engine
  // =========================================================
  renderSearchVersionSelect() {
    const select = document.getElementById("searchVersionSelect");
    select.innerHTML = "";
    this.allBibleVersions.forEach(v => {
      const opt = document.createElement("option");
      opt.value = v.id;
      opt.textContent = v.abbr || v.name;
      if (v.id === "CUV") opt.selected = true;
      select.appendChild(opt);
    });
  }

  executeSearch(term, versionId) {
    const query = term.trim().toLowerCase();
    const listContainer = document.getElementById("searchResultsList");
    const statsEl = document.getElementById("searchStats");
    listContainer.innerHTML = "";

    if (!query) {
      statsEl.textContent = "请输入关键字进行检索";
      return;
    }

    const vMap = this.getVersesMap(versionId);
    const results = [];

    for (const [key, text] of Object.entries(vMap)) {
      if (text.toLowerCase().includes(query)) {
        const [bNo, cNo, vNo] = key.split("-").map(Number);
        const bObj = BOOK_MAP.get(bNo);
        results.push({
          bookNo: bNo,
          chapNo: cNo,
          verseNo: vNo,
          refStr: `${bObj ? bObj.name : ""} ${cNo}:${vNo}`,
          text: text
        });
      }
    }

    statsEl.textContent = `在【${versionId}】中找到 ${results.length} 处匹配：`;

    if (results.length === 0) {
      listContainer.innerHTML = `<div style="padding:12px; color:var(--text-muted); font-size:12px;">未找到匹配的经文。</div>`;
      return;
    }

    results.slice(0, 50).forEach(r => {
      const row = document.createElement("div");
      row.className = "search-result-row";
      const highlightedText = escapeHtml(r.text).replace(new RegExp(escapeHtml(query), "gi"), match => `<mark style="background:#fef08a; padding:0 2px;">${match}</mark>`);
      row.innerHTML = `<span class="search-ref">${r.refStr}</span> ${highlightedText}`;
      row.addEventListener("click", () => {
        this.jumpTo(r.bookNo, r.chapNo, r.verseNo);
      });
      listContainer.appendChild(row);
    });
  }

  // =========================================================
  // General Event Listeners & Keyboard Shortcuts
  // =========================================================
  setupEventListeners() {
    // Navigation controls
    document.getElementById("chapterSelect").addEventListener("change", (e) => {
      this.currentChapter = parseInt(e.target.value);
      this.currentVerse = 1;
      this.updateVerseSelect();
      this.renderPassage();
      this.renderLeftPanel();
      this.renderCommentary();
    });

    document.getElementById("verseSelect").addEventListener("change", (e) => {
      const v = parseInt(e.target.value);
      this.setActiveVerse(v);
      const row = document.getElementById(`verse-row-${v}`) || document.getElementById(`parallel-row-${v}`);
      if (row) row.scrollIntoView({ behavior: "smooth", block: "center" });
    });

    document.getElementById("btnPrevChapter").addEventListener("click", () => this.navigateChapter(-1));
    document.getElementById("btnNextChapter").addEventListener("click", () => this.navigateChapter(1));

    // Copy Passage Button
    const cpBtn = document.getElementById("btnCopyPassage");
    if (cpBtn) {
      cpBtn.addEventListener("click", () => {
        const vMap = this.getVersesMap(this.activeVersion);
        const book = BOOK_MAP.get(this.currentBook);
        const total = this.getVersesCountForChapter(this.currentBook, this.currentChapter);
        let allTxt = `【${book ? book.name : ""} 第 ${this.currentChapter} 章】\n\n`;
        for (let v = 1; v <= total; v++) {
          const t = vMap[`${this.currentBook}-${this.currentChapter}-${v}`];
          if (t) allTxt += `${v}. ${t}\n`;
        }
        navigator.clipboard.writeText(allTxt).then(() => {
          showToast(`已复制《${book ? book.name : ""}》第 ${this.currentChapter} 章全部经文！`, "📋");
        });
      });
    }

    // Layout Mode Buttons
    document.querySelectorAll(".btn-mode").forEach(btn => {
      btn.addEventListener("click", () => {
        this.setLayoutMode(parseInt(btn.dataset.mode));
      });
    });

    // Panel Toggles
    const toggleOutlineBtn = document.getElementById("toggleOutlineBtn");
    const toggleCommentaryBtn = document.getElementById("toggleCommentaryBtn");
    const toggleDrawerBtn = document.getElementById("toggleDrawerBtn");

    toggleOutlineBtn.addEventListener("click", () => {
      const left = document.getElementById("leftPanel");
      left.style.display = (left.style.display === "none") ? "flex" : "none";
      toggleOutlineBtn.classList.toggle("active", left.style.display !== "none");
    });

    toggleCommentaryBtn.addEventListener("click", () => {
      const right = document.getElementById("rightPanel");
      right.style.display = (right.style.display === "none") ? "flex" : "none";
      toggleCommentaryBtn.classList.toggle("active", right.style.display !== "none");
    });

    toggleDrawerBtn.addEventListener("click", () => {
      const drawer = document.getElementById("bottomDrawer");
      drawer.classList.toggle("collapsed");
      toggleDrawerBtn.classList.toggle("active", !drawer.classList.contains("collapsed"));
    });

    document.getElementById("btnCloseDrawer").addEventListener("click", () => {
      document.getElementById("bottomDrawer").classList.add("collapsed");
      toggleDrawerBtn.classList.remove("active");
    });

    // Drawer Tabs
    document.querySelectorAll(".drawer-tab-btn").forEach(btn => {
      btn.addEventListener("click", () => {
        document.querySelectorAll(".drawer-tab-btn").forEach(b => b.classList.remove("active"));
        document.querySelectorAll(".drawer-view").forEach(v => v.classList.remove("active"));
        btn.classList.add("active");
        const targetView = document.getElementById(`drawerView${btn.dataset.drawerTab === "search" ? "Search" : "Lexicon"}`);
        if (targetView) targetView.classList.add("active");
      });
    });

    // Search Trigger
    document.getElementById("btnRunSearch").addEventListener("click", () => {
      const term = document.getElementById("searchInput").value;
      const ver = document.getElementById("searchVersionSelect").value;
      this.executeSearch(term, ver);
    });

    document.getElementById("searchInput").addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        const term = document.getElementById("searchInput").value;
        const ver = document.getElementById("searchVersionSelect").value;
        this.executeSearch(term, ver);
      }
    });

    // Left Panel Tabs
    document.querySelectorAll("[data-left-tab]").forEach(btn => {
      btn.addEventListener("click", () => {
        document.querySelectorAll("[data-left-tab]").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        this.activeLeftTab = btn.dataset.leftTab;
        this.renderLeftPanel();
      });
    });

    // Theme & Font Scale
    document.getElementById("themeSelect").addEventListener("change", (e) => {
      this.setTheme(e.target.value);
    });

    document.getElementById("btnFontDec").addEventListener("click", () => this.adjustFontSize(-1));
    document.getElementById("btnFontInc").addEventListener("click", () => this.adjustFontSize(1));

    // Popover Close
    document.getElementById("btnCloseStrongPopover").addEventListener("click", () => {
      document.getElementById("strongPopover").style.display = "none";
    });

    // Setup Manage Modal
    this.setupManageModal();

    // Global Keyboard navigation
    window.addEventListener("keydown", (e) => {
      const activeTag = document.activeElement ? document.activeElement.tagName.toLowerCase() : "";
      if (activeTag === "input" || activeTag === "textarea") return;

      if (e.key === "[" || e.key === "ArrowLeft") {
        this.navigateChapter(-1);
      } else if (e.key === "]" || e.key === "ArrowRight") {
        this.navigateChapter(1);
      } else if (e.key === "j" || e.key === "ArrowDown") {
        e.preventDefault();
        const total = this.getVersesCountForChapter(this.currentBook, this.currentChapter);
        if (this.currentVerse < total) {
          this.setActiveVerse(this.currentVerse + 1);
          const row = document.getElementById(`verse-row-${this.currentVerse}`);
          if (row) row.scrollIntoView({ behavior: "smooth", block: "nearest" });
        }
      } else if (e.key === "k" || e.key === "ArrowUp") {
        e.preventDefault();
        if (this.currentVerse > 1) {
          this.setActiveVerse(this.currentVerse - 1);
          const row = document.getElementById(`verse-row-${this.currentVerse}`);
          if (row) row.scrollIntoView({ behavior: "smooth", block: "nearest" });
        }
      } else if (e.key === " ") {
        e.preventDefault();
        this.toggleTts();
      } else if (["1", "2", "3", "4"].includes(e.key)) {
        this.setLayoutMode(parseInt(e.key));
      }
    });
  }

  // =========================================================
  // Resource Manager (Import / Backup / Restore)
  // =========================================================
  setupManageModal() {
    const modal = document.getElementById("manageModal");

    document.getElementById("btnOpenManageModal").addEventListener("click", () => {
      modal.style.display = "flex";
      this.renderInstalledModulesList();
      const cBookSelect = document.getElementById("importCommBookSelect");
      cBookSelect.innerHTML = "";
      BIBLE_BOOKS.forEach(b => {
        const opt = document.createElement("option");
        opt.value = b.no;
        opt.textContent = `${b.name} (${b.abbr})`;
        if (b.no === this.currentBook) opt.selected = true;
        cBookSelect.appendChild(opt);
      });
    });

    document.getElementById("btnCloseManageModal").addEventListener("click", () => {
      modal.style.display = "none";
    });

    document.querySelectorAll("[data-modal-tab]").forEach(btn => {
      btn.addEventListener("click", () => {
        document.querySelectorAll("[data-modal-tab]").forEach(b => b.classList.remove("active"));
        document.querySelectorAll(".modal-tab-pane").forEach(p => p.classList.remove("active"));
        btn.classList.add("active");
        const targetPane = document.getElementById(`modalPane-${btn.dataset.modalTab}`);
        if (targetPane) targetPane.classList.add("active");
      });
    });

    this.setupDropzone("bibleDropzone", "bibleFileInput", "biblePasteArea");
    this.setupDropzone("commDropzone", "commFileInput", "commPasteArea");

    document.getElementById("btnDownloadBibleJsonTemplate").addEventListener("click", () => this.downloadTemplate("bible-json"));
    document.getElementById("btnDownloadBibleCsvTemplate").addEventListener("click", () => this.downloadTemplate("bible-csv"));
    document.getElementById("btnDownloadCommJsonTemplate").addEventListener("click", () => this.downloadTemplate("comm-json"));

    document.getElementById("btnParseBible").addEventListener("click", () => this.parseAndImportBible());
    document.getElementById("btnParseComm").addEventListener("click", () => this.parseAndImportCommentary());

    document.getElementById("btnExportAllData").addEventListener("click", () => this.exportAllUserData());

    document.getElementById("btnResetToDefaults").addEventListener("click", async () => {
      if (confirm("确定要清空所有自定义导入的译本、注释和高亮笔记吗？此操作不可逆！")) {
        indexedDB.deleteDatabase("BibleWorkbenchDB");
        location.reload();
      }
    });

    document.getElementById("btnRestoreAllData").addEventListener("click", () => {
      const input = document.getElementById("restoreFileInput");
      if (!input.files || input.files.length === 0) {
        alert("请先选择备份 JSON 文件！");
        return;
      }
      const reader = new FileReader();
      reader.onload = async (e) => {
        try {
          const data = JSON.parse(e.target.result);
          if (data.customBibles) {
            for (const b of data.customBibles) await db.saveCustomBible(b);
          }
          if (data.customCommentaries) {
            for (const c of data.customCommentaries) await db.saveCustomCommentary(c);
          }
          if (data.highlights) {
            for (const h of data.highlights) await db.saveHighlight(h);
          }
          if (data.notes) {
            for (const n of data.notes) await db.saveNote(n);
          }
          alert("备份数据还原成功！页面即将刷新。");
          location.reload();
        } catch (err) {
          alert("还原失败: " + err.message);
        }
      };
      reader.readAsText(input.files[0]);
    });
  }

  setupDropzone(zoneId, fileInputId, pasteAreaId) {
    const zone = document.getElementById(zoneId);
    const fileInput = document.getElementById(fileInputId);
    const pasteArea = document.getElementById(pasteAreaId);

    zone.addEventListener("click", () => fileInput.click());

    fileInput.addEventListener("change", () => {
      if (fileInput.files && fileInput.files[0]) {
        const f = fileInput.files[0];
        const reader = new FileReader();
        reader.onload = (e) => { pasteArea.value = e.target.result; };
        reader.readAsText(f);
      }
    });

    zone.addEventListener("dragover", (e) => { e.preventDefault(); zone.style.borderColor = "var(--primary)"; });
    zone.addEventListener("dragleave", () => { zone.style.borderColor = "var(--border-color)"; });
    zone.addEventListener("drop", (e) => {
      e.preventDefault();
      zone.style.borderColor = "var(--border-color)";
      if (e.dataTransfer.files && e.dataTransfer.files[0]) {
        const f = e.dataTransfer.files[0];
        const reader = new FileReader();
        reader.onload = (ev) => { pasteArea.value = ev.target.result; };
        reader.readAsText(f);
      }
    });
  }

  downloadTemplate(type) {
    let content = "";
    let filename = "";

    if (type === "bible-json") {
      filename = "bible-template.json";
      content = JSON.stringify({
        id: "LZZ",
        name: "吕振中译本",
        abbreviation: "吕振中",
        verses: {
          "64-1-1": "作长老的、写信给亲爱的该犹、就是我在真实中所爱的。",
          "64-1-2": "亲爱的、我祝你事事亨通，身体健壮，正如你的灵魂亨通一样。",
          "64-1-3": "有弟兄们来，见证你在真理中，正如你按真理而行，我就非常喜欢。"
        }
      }, null, 2);
    } else if (type === "bible-csv") {
      filename = "bible-template.csv";
      content = "书卷号,章,节,经文内容\n64,1,1,作长老的、写信给亲爱的该犹、就是我在真实中所爱的。\n64,1,2,亲爱的、我祝你事事亨通，身体健壮，正如你的灵魂亨通一样。\n64,1,3,有弟兄们来，见证你在真理中，正如你按真理而行，我就非常喜欢。";
    } else if (type === "comm-json") {
      filename = "commentary-template.json";
      content = JSON.stringify({
        id: "calvin-notes",
        title: "加尔文解经集萃",
        author: "约翰·加尔文",
        book: 64,
        intro: "约翰在此教导我们在真实爱心接待中见证主道...",
        verses: {
          "1": "【第1节评注】神圣的长老职分建立在服事众人的谦卑品格中。",
          "2": "【第2节评注】身体与灵魂的康泰乃是信徒在地上事奉主不可或缺的保障。"
        }
      }, null, 2);
    }

    const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  async parseAndImportBible() {
    const id = document.getElementById("importBibleId").value.trim().toUpperCase();
    const name = document.getElementById("importBibleName").value.trim();
    const abbr = document.getElementById("importBibleAbbr").value.trim() || id;
    const format = document.getElementById("importBibleFormat").value;
    const rawText = document.getElementById("biblePasteArea").value.trim();
    const statusEl = document.getElementById("bibleImportStatus");

    if (!id || !name) {
      statusEl.className = "status-msg error";
      statusEl.textContent = "请填写译本唯一 ID 和全称！";
      return;
    }
    if (!rawText) {
      statusEl.className = "status-msg error";
      statusEl.textContent = "请提供经文数据（拖入文件或粘贴内容）！";
      return;
    }

    try {
      let versesMap = {};

      if (format === "json") {
        const parsed = JSON.parse(rawText);
        versesMap = parsed.verses || parsed;
      } else if (format === "csv") {
        const lines = rawText.split("\n");
        lines.forEach(l => {
          const parts = l.split(",");
          if (parts.length >= 4 && !isNaN(parseInt(parts[0]))) {
            const b = parseInt(parts[0]);
            const c = parseInt(parts[1]);
            const v = parseInt(parts[2]);
            const t = parts.slice(3).join(",").trim();
            versesMap[`${b}-${c}-${v}`] = t;
          }
        });
      } else if (format === "lines") {
        const lines = rawText.split("\n");
        lines.forEach(l => {
          const m = l.match(/^(\d+)\s+(\d+):(\d+)\s+(.*)$/);
          if (m) {
            versesMap[`${m[1]}-${m[2]}-${m[3]}`] = m[4].trim();
          }
        });
      }

      const count = Object.keys(versesMap).length;
      if (count === 0) throw new Error("未能解析出任何经文条目，请检查数据格式");

      const bibleObj = {
        id: id,
        name: name,
        abbr: abbr,
        lang: "zh",
        verses: versesMap,
        updatedAt: new Date().toISOString()
      };

      await db.saveCustomBible(bibleObj);

      this.customBibles = await db.getAllCustomBibles();
      this.allBibleVersions = [...BUILTIN_BIBLES, ...this.customBibles];

      statusEl.className = "status-msg success";
      statusEl.textContent = `成功导入【${name}】！共解析 ${count} 节经文。`;

      this.renderVersionTabs();
      this.renderInstalledModulesList();
    } catch (err) {
      statusEl.className = "status-msg error";
      statusEl.textContent = `解析失败: ${err.message}`;
    }
  }

  async parseAndImportCommentary() {
    const id = document.getElementById("importCommId").value.trim().toLowerCase();
    const title = document.getElementById("importCommTitle").value.trim();
    const author = document.getElementById("importCommAuthor").value.trim() || "自定义";
    const bookNo = parseInt(document.getElementById("importCommBookSelect").value);
    const rawText = document.getElementById("commPasteArea").value.trim();
    const statusEl = document.getElementById("commImportStatus");

    if (!id || !title) {
      statusEl.className = "status-msg error";
      statusEl.textContent = "请填写注释书 ID 和名称！";
      return;
    }
    if (!rawText) {
      statusEl.className = "status-msg error";
      statusEl.textContent = "请粘贴注释 JSON 数据！";
      return;
    }

    try {
      const parsed = JSON.parse(rawText);
      const commObj = {
        id: id,
        title: title,
        author: author,
        book: bookNo,
        intro: parsed.intro || "",
        verses: parsed.verses || {},
        updatedAt: new Date().toISOString()
      };

      await db.saveCustomCommentary(commObj);

      this.customCommentaries = await db.getAllCustomCommentaries();

      statusEl.className = "status-msg success";
      statusEl.textContent = `成功导入注释【${title}】！已保存。`;

      this.renderCommentaryTabs();
      this.renderInstalledModulesList();
    } catch (err) {
      statusEl.className = "status-msg error";
      statusEl.textContent = `解析失败: ${err.message}`;
    }
  }

  renderInstalledModulesList() {
    const bList = document.getElementById("installedBiblesList");
    const cList = document.getElementById("installedCommsList");

    bList.innerHTML = "";
    cList.innerHTML = "";

    BUILTIN_BIBLES.forEach(b => {
      const item = document.createElement("div");
      item.className = "installed-item";
      item.innerHTML = `
        <div class="installed-info">
          <span class="installed-name">${b.name} (${b.abbr})</span>
          <span class="installed-badge">系统内置</span>
        </div>
        <div class="installed-actions">
          <button class="btn btn-xs btn-ghost" disabled>系统预装</button>
        </div>
      `;
      bList.appendChild(item);
    });

    this.customBibles.forEach(b => {
      const count = Object.keys(b.verses || {}).length;
      const item = document.createElement("div");
      item.className = "installed-item";
      item.innerHTML = `
        <div class="installed-info">
          <span class="installed-name">${b.name} (${b.abbr})</span>
          <span class="installed-badge" style="background-color:#dcfce7; color:#166534;">自定义 (${count} 节)</span>
        </div>
        <div class="installed-actions">
          <button class="btn btn-xs btn-danger btn-del-bible" data-id="${b.id}"><i class="fa-solid fa-trash-can"></i> 删除</button>
        </div>
      `;
      item.querySelector(".btn-del-bible").addEventListener("click", async () => {
        if (confirm(`确定要从本地数据库删除译本【${b.name}】吗？`)) {
          await db.deleteCustomBible(b.id);
          this.customBibles = await db.getAllCustomBibles();
          this.allBibleVersions = [...BUILTIN_BIBLES, ...this.customBibles];
          this.renderVersionTabs();
          this.renderInstalledModulesList();
        }
      });
      bList.appendChild(item);
    });

    const builtinComms = [
      { id: "burdick", title: "伯迪克注释", author: "唐纳德·伯迪克" },
      { id: "believers", title: "信徒圣经注释", author: "威廉·麦克唐纳" },
      { id: "macarthur", title: "讲道与解经", author: "约翰·麦克阿瑟" }
    ];
    builtinComms.forEach(c => {
      const item = document.createElement("div");
      item.className = "installed-item";
      item.innerHTML = `
        <div class="installed-info">
          <span class="installed-name">${c.title}</span>
          <span class="installed-badge">系统内置 (${c.author})</span>
        </div>
        <div class="installed-actions">
          <button class="btn btn-xs btn-ghost" disabled>系统预装</button>
        </div>
      `;
      cList.appendChild(item);
    });

    this.customCommentaries.forEach(c => {
      const count = Object.keys(c.verses || {}).length;
      const item = document.createElement("div");
      item.className = "installed-item";
      item.innerHTML = `
        <div class="installed-info">
          <span class="installed-name">${c.title}</span>
          <span class="installed-badge" style="background-color:#dcfce7; color:#166534;">自定义 (${count} 条)</span>
        </div>
        <div class="installed-actions">
          <button class="btn btn-xs btn-danger btn-del-comm" data-id="${c.id}"><i class="fa-solid fa-trash-can"></i> 删除</button>
        </div>
      `;
      item.querySelector(".btn-del-comm").addEventListener("click", async () => {
        if (confirm(`确定要删除注释【${c.title}】吗？`)) {
          await db.deleteCustomCommentary(c.id);
          this.customCommentaries = await db.getAllCustomCommentaries();
          this.renderCommentaryTabs();
          this.renderInstalledModulesList();
        }
      });
      cList.appendChild(item);
    });
  }

  async exportAllUserData() {
    const data = {
      version: 2,
      exportDate: new Date().toISOString(),
      customBibles: this.customBibles,
      customCommentaries: this.customCommentaries,
      highlights: Array.from(this.highlights.values()),
      notes: Array.from(this.notes.values())
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `bible-workbench-backup-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    showToast("整站用户数据备份导出成功！", "💾");
  }

  // =========================================================
  // Layout, Theme, Font Size & Preferences
  // =========================================================
  navigateChapter(direction) {
    const book = BOOK_MAP.get(this.currentBook);
    const maxChap = book ? book.chapters : 1;

    let newChap = this.currentChapter + direction;
    if (newChap < 1) {
      if (this.currentBook > 1) {
        this.currentBook--;
        const prevBook = BOOK_MAP.get(this.currentBook);
        this.currentChapter = prevBook ? prevBook.chapters : 1;
      } else {
        return;
      }
    } else if (newChap > maxChap) {
      if (this.currentBook < 66) {
        this.currentBook++;
        this.currentChapter = 1;
      } else {
        return;
      }
    } else {
      this.currentChapter = newChap;
    }

    this.currentVerse = 1;
    document.getElementById("bookSelect").value = this.currentBook;
    this.updateChapterSelect();
    document.getElementById("chapterSelect").value = this.currentChapter;
    this.updateVerseSelect();

    this.renderPassage();
    this.renderLeftPanel();
    this.renderBookIntro();
    this.renderCommentary();
  }

  setLayoutMode(mode) {
    this.layoutMode = mode;
    document.body.dataset.layout = mode;
    document.querySelectorAll(".btn-mode").forEach(btn => {
      btn.classList.toggle("active", parseInt(btn.dataset.mode) === mode);
    });

    const left = document.getElementById("leftPanel");
    const center = document.getElementById("centerPanel");
    const right = document.getElementById("rightPanel");
    left.style.display = "";
    center.style.display = "";
    right.style.display = "";

    this.renderPassage();
  }

  setTheme(theme) {
    document.body.className = document.body.className.replace(/theme-\w+/, `theme-${theme}`);
    localStorage.setItem("bible_workbench_theme", theme);
  }

  adjustFontSize(delta) {
    const sizes = ["font-s", "font-m", "font-l", "font-xl"];
    let curIdx = sizes.findIndex(s => document.body.classList.contains(s));
    if (curIdx === -1) curIdx = 1;
    const newIdx = Math.max(0, Math.min(sizes.length - 1, curIdx + delta));
    sizes.forEach(s => document.body.classList.remove(s));
    document.body.classList.add(sizes[newIdx]);
    localStorage.setItem("bible_workbench_fontsize", sizes[newIdx]);
  }

  loadSavedPreferences() {
    const savedTheme = localStorage.getItem("bible_workbench_theme") || "light";
    this.setTheme(savedTheme);
    const tSel = document.getElementById("themeSelect");
    if (tSel) tSel.value = savedTheme;

    const savedSize = localStorage.getItem("bible_workbench_fontsize") || "font-m";
    ["font-s", "font-m", "font-l", "font-xl"].forEach(s => document.body.classList.remove(s));
    document.body.classList.add(savedSize);

    try {
      const savedParallel = localStorage.getItem("bible_parallel_versions");
      if (savedParallel) {
        const parsed = JSON.parse(savedParallel);
        if (Array.isArray(parsed) && parsed.length > 0) this.parallelVersions = parsed;
      }
    } catch (e) {}
  }
}

// Utility Helpers
function escapeHtml(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function showToast(msg, icon = "✅") {
  const toast = document.getElementById("toast");
  const iconEl = document.getElementById("toastIcon");
  const msgEl = document.getElementById("toastMsg");
  if (!toast) return;

  if (iconEl) iconEl.textContent = icon;
  if (msgEl) msgEl.textContent = msg;

  toast.classList.add("show");
  setTimeout(() => {
    toast.classList.remove("show");
  }, 3500);
}

// Start app on DOMContentLoaded
window.addEventListener("DOMContentLoaded", () => {
  window.workbenchApp = new BibleWorkbenchApp();
  window.workbenchApp.init();
});
